configure.example:
kcds.world.Trees.configure({
  hits: 5,
  regrowMinutes: 60,
  drops: [{ item: 'bsmt_woodExotic', amount: 3 }],
});

setSpecies.example:
// Oaks are tall and hard.
kcds.world.Trees.setSpecies('objects/natural/vegetation/trees/normal_trees/quercus', {
  hits: 14,
  height: 22,
});

isTree.exampleCs:
Events.On("playerWeaponHit", (Player player, JsValue hit) =>
{
    if (hit["levelObject"] && Trees.IsTree(hit["levelObject"]["name"]))
    {
        Log.Info("a tree");
    }
});

get.example:
const birchId = 'objects/natural/vegetation/trees/normal_trees/betula_pendula/betula_pendula_a.cgf@10,20,30';
const birch = kcds.world.Trees.get(birchId);
if (birch) {
  console.info(birch.state);
}

get.exampleCs:
var birchId = "objects/natural/vegetation/trees/normal_trees/betula_pendula/betula_pendula_a.cgf@10,20,30";
var birch = Trees.Get(birchId);
if (birch)
{
    Log.Info(birch["state"]);
}

of.example:
// A storm fells the tree a client's ray found.
kcds.core.Events.fromClient('storm', (player, object) => {
  kcds.world.Trees.of(object)?.fell(new kcds.math.Vector3(1, 0, 0));
});

of.exampleCs:
// A storm fells the tree a client's ray found.
Events.FromClient("storm", (Player player, JsValue @object) =>
{
    Trees.Of(@object).Call("fell", new Vector3(1, 0, 0));
});

state.exampleCs:
// C# scripts have no files: a JavaScript resource of yours, "storage", keeps the state
Events.On("resourceStop", () =>
{
    Exports.Get("storage", "save").Invoke("forest", Trees.State());
});

restore.example:
const fs = require('node:fs');

if (fs.existsSync(forestFile)) {
  const restored = kcds.world.Trees.restore(JSON.parse(fs.readFileSync(forestFile, 'utf8')));
  console.info(`${restored} trees restored`);
}

restore.exampleCs:
// C# scripts have no files: a JavaScript resource of yours, "storage", keeps the state
var saved = Exports.Get("storage", "load").Invoke("forest");
if (!saved.IsNull)
{
    var restored = Trees.Restore(saved);
    Log.Info($"{restored} trees restored");
}
